tool_input.oldString:
// Re-query y stepper after x update re-render
const yStepperInputRefreshed = page.locator(`${panel} input[id="semio.sketchpad.app.design.panel.details.section.connection.y"]`).first();
await expect(yStepperInputRefreshed).toBeVisible();
// Use native value setter + React-compatible events to reliably update controlled input
await page.evaluate((value: string) => {
  const input = document.getElementById("semio.sketchpad.app.design.panel.details.section.connection.y") as HTMLInputElement;
  if (!input) throw new Error("Y stepper input not found");
  input.focus();
  const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, "value")!.set!;
  nativeInputValueSetter.call(input, value);
  input.dispatchEvent(new Event("input", { bubbles: true }));
  input.dispatchEvent(new Event("change", { bubbles: true }));
}, String(testYValue));
await yStepperInputRefreshed.press("Enter");
await page.waitForTimeout(2000);
